"""Procedural snow for the Post-processing page (post_process.py's "snow"
action).

Every face of the map's terrain gets a snow score, built from factors that
each blend in smoothly instead of acting as a hard gate:

- height: a snow threshold (% of the terrain height, like Color by Height)
  with a soft transition band -- more snow higher up;
- slope: snow slides off steep ground, fading out towards the max slope
  (judged on normals averaged over a few of the map's own triangles, so
  terraced ground reads as the slope it forms);
- hollows: dips and gullies hold snow, exposed ridges lose it;
- noise: layered value noise for organic, patchy outlines (the page's
  Patchiness and Patch size).

"Coverage" then keeps the best-scoring part of the ground that can hold
snow at all (above the snow threshold band, not too steep) -- so there is
snow on any map, a flat one included. Patches smaller than MIN_PATCH_MM are
dropped and holes as small filled, so everything left can print.

The snow is painted onto the map, nothing is added -- always exactly the
faces the page's preview shows: into its paint texture, every pixel on one
of them (paint_snow_into_texture), or onto those faces as a white material
on a map colored by face materials (paint_snow_onto_faces). Water, roads,
buildings and trails are never painted over.

The page shows only coverage, snow threshold, max slope, patchiness, patch
size and seed; the rest are the fixed values below.
"""

import math
from collections import deque

import numpy as np

# The map's side walls: (near) vertical faces reaching down to its bottom.
WALL_NORMAL_Z = 0.02
# Grid cells for the smoothing / hollow blurs.
MAX_GRID_CELLS = 1_500_000

# Fixed settings (the page shows only coverage, snow threshold, max slope,
# patchiness, patch size and seed):
# width of the snow threshold's soft band, in % of the terrain height;
THRESHOLD_SOFTNESS = 15.0
# snow thins out over this many degrees below the max slope;
SLOPE_SOFTNESS_DEG = 10.0
# how much more snow hollows get than exposed ridges (0..1);
HOLLOWS = 0.3
# patches smaller than about this wide are dropped, holes as small filled;
MIN_PATCH_MM = 1.5
# slopes are judged on normals averaged over this many of the map's own
# triangles (so terraced ground reads as the slope it forms), within limits.
AUTO_SMOOTHING_TRIANGLES = 4.0
AUTO_SMOOTHING_RANGE_MM = (0.5, 10.0)


def _smoothstep(edge0, edge1, x):
    if edge1 <= edge0:
        return (x >= edge0).astype(np.float64)
    t = np.clip((x - edge0) / (edge1 - edge0), 0.0, 1.0)
    return t * t * (3.0 - 2.0 * t)


class SnowSurface:
    """A map's terrain as triangles in world mm -- built once per map and
    reused for every preview, with the per-setting pieces (smoothed
    normals, hollows, noise, face adjacency) cached as they're first
    needed."""

    def __init__(self, map_obj, depsgraph, height_range=None):
        self.name = map_obj.name
        self.origin = np.array(map_obj.matrix_world.translation, dtype=np.float64)
        evaluated = map_obj.evaluated_get(depsgraph)
        mesh = evaluated.to_mesh()
        try:
            mesh.calc_loop_triangles()
            n = len(mesh.loop_triangles)
            tris = np.empty(n * 3, dtype=np.int64)
            mesh.loop_triangles.foreach_get("vertices", tris)
            # The polygon each triangle belongs to -- what the face-material
            # paint recolors.
            self.poly = np.empty(n, dtype=np.int64)
            mesh.loop_triangles.foreach_get("polygon_index", self.poly)
            self.poly_count = len(mesh.polygons)
            co = np.empty(len(mesh.vertices) * 3, dtype=np.float64)
            mesh.vertices.foreach_get("co", co)
        finally:
            evaluated.to_mesh_clear()
        mw = np.array(map_obj.matrix_world, dtype=np.float64)
        co = co.reshape(-1, 3) @ mw[:3, :3].T + mw[:3, 3]
        tris = tris.reshape(-1, 3)
        # Weld by position, so faces that only share a location still count
        # as neighbours.
        _unique, inverse = np.unique(np.round(co, 4), axis=0, return_inverse=True)
        inverse = inverse.ravel()
        welded = np.zeros((inverse.max() + 1 if len(inverse) else 0, 3))
        welded[inverse] = co
        self.co = welded
        self.tris = inverse[tris]
        a, b, c = (self.co[self.tris[:, k]] for k in range(3))
        normals = np.cross(b - a, c - a)
        lengths = np.linalg.norm(normals, axis=1)
        valid = lengths > 1e-12
        normals[valid] /= lengths[valid, None]
        normals[~valid] = 0.0
        self.normals = normals
        self.areas = lengths * 0.5
        self.centroids = (a + b + c) / 3.0
        self.edge = float(np.linalg.norm(b - a, axis=1).mean()) if len(a) else 1.0
        bottom = float(self.co[:, 2].min()) if len(self.co) else 0.0
        touches_bottom = (np.stack([a[:, 2], b[:, 2], c[:, 2]], axis=1) <= bottom + 1e-3).any(axis=1)
        self.wall = (np.abs(normals[:, 2]) < WALL_NORMAL_Z) & touches_bottom
        # Terrain: the upward-facing surface, without the side walls.
        self.terrain = ~self.wall & (normals[:, 2] > 0.0)
        # Smoothing when none is given: a few of the terrain's own
        # triangles wide (sqrt(2 * area) ~ the grid spacing).
        spacing = float(np.sqrt(2.0 * np.median(self.areas[self.terrain]))) if self.terrain.any() else 1.0
        low_mm, high_mm = AUTO_SMOOTHING_RANGE_MM
        self.auto_smoothing = min(max(AUTO_SMOOTHING_TRIANGLES * spacing, low_mm), high_mm)
        # Color by Height's 0-100 % range in world Z (low, high).
        if height_range is None:
            z = self.co[:, 2]
            height_range = (float(z.min()), float(z.max()))
        self.height_range = height_range
        self.size = float(max(np.ptp(self.centroids[:, 0]), np.ptp(self.centroids[:, 1]), 1.0)) if len(a) else 1.0
        self._smoothed = {}
        self._hollows = {}
        self._noise = {}
        self._adjacency = None

    # -- grid blur (smoothing, hollows) -----------------------------------

    def _grid(self, radius):
        """(cell, nx, ny, ix, iy) of an XY grid over the faces' centres."""
        cx, cy = self.centroids[:, 0], self.centroids[:, 1]
        minx, miny = float(cx.min()), float(cy.min())
        cell = max(self.edge, radius / 12.0, 1e-3)
        nx = int((float(cx.max()) - minx) / cell) + 1
        ny = int((float(cy.max()) - miny) / cell) + 1
        if nx * ny > MAX_GRID_CELLS:
            cell *= math.sqrt(nx * ny / MAX_GRID_CELLS)
            nx = int((float(cx.max()) - minx) / cell) + 1
            ny = int((float(cy.max()) - miny) / cell) + 1
        ix = np.minimum(((cx - minx) / cell).astype(np.int64), nx - 1)
        iy = np.minimum(((cy - miny) / cell).astype(np.int64), ny - 1)
        return cell, nx, ny, ix, iy

    def _box_sum(self, values, use, radius):
        """Per face: the sum of *values* (N, k) of the *use* faces whose
        centres lie in a square of about 2 * *radius* mm around its own --
        a summed-area table over an XY grid, not a per-face search."""
        cell, nx, ny, ix, iy = self._grid(radius)
        k = values.shape[1]
        acc = np.zeros((ny + 1, nx + 1, k))
        np.add.at(acc, (iy[use] + 1, ix[use] + 1), values[use])
        table = acc.cumsum(axis=0).cumsum(axis=1)
        r = max(1, int(round(radius / cell)))
        y0, y1 = np.clip(iy - r, 0, ny), np.clip(iy + r + 1, 0, ny)
        x0, x1 = np.clip(ix - r, 0, nx), np.clip(ix + r + 1, 0, nx)
        return table[y1, x1] - table[y0, x1] - table[y1, x0] + table[y0, x0]

    def smoothed_normals(self, radius):
        """Each face's normal averaged (area-weighted) over the terrain
        within about *radius* mm -- a terraced hillside of flat steps and
        steep risers reads as the slope it is. Walls keep their own;
        *radius* <= 0 gives the faces' own normals."""
        if radius <= 0 or not len(self.tris):
            return self.normals
        key = round(float(radius), 3)
        if key not in self._smoothed:
            summed = self._box_sum(self.normals * self.areas[:, None], self.terrain, radius)
            lengths = np.linalg.norm(summed, axis=1)
            result = self.normals.copy()
            ok = (lengths > 1e-12) & ~self.wall
            result[ok] = summed[ok] / lengths[ok, None]
            self._smoothed[key] = result
        return self._smoothed[key]

    def hollows(self):
        """Per face, -1 (exposed ridge) .. 1 (hollow): how far it lies below
        the average terrain around it (within ~4 % of the map's size),
        relative to how much that varies across the map."""
        if "h" not in self._hollows:
            radius = max(3.0, self.size * 0.04)
            weights = self.areas[:, None]
            summed = self._box_sum(np.hstack([self.centroids[:, 2:3] * weights, weights]), self.terrain, radius)
            mean = np.where(summed[:, 1] > 1e-12, summed[:, 0] / np.maximum(summed[:, 1], 1e-12), self.centroids[:, 2])
            depth = mean - self.centroids[:, 2]
            spread = float(np.std(depth[self.terrain])) if self.terrain.any() else 0.0
            self._hollows["h"] = np.clip(depth / (2.0 * spread), -1.0, 1.0) if spread > 1e-9 else np.zeros(len(depth))
        return self._hollows["h"]

    def noise(self, scale, seed):
        """Per face, about -1..1: three octaves of smooth value noise at
        its centre (Scale = how fine the main octave is, per mm)."""
        key = (round(float(scale), 4), int(seed))
        if key not in self._noise:
            from .texture import _value_noise_field

            x, y = self.centroids[:, 0], self.centroids[:, 1]
            total = np.zeros(len(x))
            weight = 0.0
            for octave, amp in enumerate((1.0, 0.5, 0.25)):
                total += amp * _value_noise_field(x, y, scale * (2 ** octave), seed=seed * 3 + octave)
                weight += amp
            self._noise[key] = total / weight
        return self._noise[key]

    def adjacency(self):
        """Per face: the faces sharing an edge with it (python lists)."""
        if self._adjacency is None:
            m = len(self.tris)
            edges = np.concatenate([self.tris[:, [0, 1]], self.tris[:, [1, 2]], self.tris[:, [2, 0]]])
            owner = np.tile(np.arange(m, dtype=np.int64), 3)
            edges.sort(axis=1)
            key = edges[:, 0] * (len(self.co) + 1) + edges[:, 1]
            order = np.argsort(key, kind="stable")
            key, owner = key[order], owner[order]
            same = key[1:] == key[:-1]
            a, b = owner[:-1][same], owner[1:][same]
            src = np.concatenate([a, b])
            dst = np.concatenate([b, a])
            order = np.argsort(src, kind="stable")
            dst_list = dst[order].tolist()
            bounds = np.searchsorted(src[order], np.arange(m + 1)).tolist()
            self._adjacency = [dst_list[bounds[i]:bounds[i + 1]] for i in range(m)]
        return self._adjacency

    # -- the snow -----------------------------------------------------------

    def score(self, p):
        """(score per face, eligible mask): eligible faces can hold snow at
        all; the score ranks them."""
        low, high = self.height_range
        span = max(high - low, 1e-6)
        t = (self.centroids[:, 2] - low) / span * 100.0
        soft = max(p["softness"], 0.0)
        height = _smoothstep(p["snowline"] - soft / 2.0, p["snowline"] + soft / 2.0, t)

        smoothing = p.get("smoothing")
        normals = self.smoothed_normals(self.auto_smoothing if smoothing is None else smoothing)
        angle = np.degrees(np.arccos(np.clip(normals[:, 2], -1.0, 1.0)))
        slope = 1.0 - _smoothstep(p["maxSlope"] - max(p["slopeSoftness"], 0.0), p["maxSlope"], angle)

        base = height * slope
        eligible = self.terrain & (base > 1e-6)
        score = base + 0.5 * p["hollows"] * self.hollows()
        if p["amplitude"] > 0:
            score = score + p["amplitude"] * self.noise(p["scale"], p["seed"])
        return score, eligible

    def cover(self, p):
        """Boolean mask of the faces that get snow."""
        covered = np.zeros(len(self.tris), dtype=bool)
        score, eligible = self.score(p)
        if not eligible.any() or p["coverage"] <= 0:
            return covered
        # The best-scoring faces up to Coverage % of the eligible area.
        idx = np.nonzero(eligible)[0]
        order = idx[np.argsort(-score[idx], kind="stable")]
        cumulative = np.cumsum(self.areas[order])
        wanted = cumulative[-1] * min(p["coverage"], 100.0) / 100.0
        covered[order[:int(np.searchsorted(cumulative, wanted, side="right"))]] = True
        if p["minPatch"] > 0:
            covered = self._clean(covered, eligible, p["minPatch"] ** 2)
        return covered

    def _clean(self, covered, eligible, min_area):
        """Drop snow patches smaller than *min_area* mm² and fill holes
        smaller than it (uncovered spots enclosed by snow)."""
        adjacency = self.adjacency()
        areas = self.areas
        covered = covered.copy()
        # Small patches go.
        seen = np.zeros(len(covered), dtype=bool)
        for start in np.nonzero(covered)[0].tolist():
            if seen[start]:
                continue
            component, total = self._component(start, covered, seen, adjacency, areas)
            if total < min_area:
                covered[component] = False
        # Small holes fill: an uncovered stretch of terrain next to snow,
        # surrounded by it, smaller than the limit. Explored only up to the
        # limit -- anything larger is open ground, not a hole.
        seen = np.zeros(len(covered), dtype=bool)
        open_ground = self.terrain & ~covered
        for face in np.nonzero(covered)[0].tolist():
            for start in adjacency[face]:
                if not open_ground[start] or seen[start]:
                    continue
                component, total = self._component(start, open_ground, seen, adjacency, areas, limit=min_area)
                if total < min_area and component and eligible[component].all():
                    covered[component] = True
        return covered

    @staticmethod
    def _component(start, mask, seen, adjacency, areas, limit=None):
        """(faces, area) of the *mask* region around *start* -- stops
        counting once the area passes *limit*."""
        queue = deque([start])
        seen[start] = True
        faces, total = [], 0.0
        while queue:
            f = queue.popleft()
            faces.append(f)
            total += areas[f]
            if limit is not None and total >= limit:
                # Too big to be a hole: mark the rest of it as seen lazily.
                return faces, total
            for nb in adjacency[f]:
                if mask[nb] and not seen[nb]:
                    seen[nb] = True
                    queue.append(nb)
        return faces, total


    def preview_triangles(self, covered, lift=0.05):
        """[x0, y0, z0, x1, ...] of the covered faces, lifted *lift* mm so
        they show over the terrain -- the page's preview of the paint."""
        pts = self.co[self.tris[covered]].reshape(-1, 3).copy()
        pts[:, 2] += lift
        return pts


# ── Painting ──────────────────────────────────────────────────────────────

SNOW_SRGB = (255, 255, 255)
# Snow never covers these: they'd be lost under it.
PROTECTED_ROLES = ("WATER", "BUILDINGS", "ROADS", "TRAIL", "YELLOW")


def _protected_colors(mesh):
    from .color_styles import material_role_colors, read_mesh_color_roles

    roles = read_mesh_color_roles(mesh, material_role_colors())
    return [tuple(int(c) for c in roles[r]) for r in PROTECTED_ROLES if r in roles]


def _rasterize_triangles(tris_px, res):
    """Boolean res x res grid: pixels whose centre lies inside any of
    *tris_px* ((K, 3, 2) corners in pixel units, x = column, y = row).
    Vectorised: each triangle tests the pixels of its own bounding box,
    in batches of similar size so the work stays bounded."""
    mask = np.zeros((res, res), dtype=bool)
    if not len(tris_px):
        return mask
    lo = np.floor(tris_px.min(axis=1) - 0.5).astype(np.int64)    # first candidate centre
    hi = np.ceil(tris_px.max(axis=1) - 0.5).astype(np.int64)     # last candidate centre
    span = np.maximum(hi - lo + 1, 1).max(axis=1)
    for size in np.unique(np.minimum(2 ** np.ceil(np.log2(span)).astype(np.int64), res)):
        group = np.nonzero(np.minimum(2 ** np.ceil(np.log2(span)).astype(np.int64), res) == size)[0]
        oy, ox = np.mgrid[0:size, 0:size]
        offsets = np.stack([ox.ravel(), oy.ravel()], axis=1)  # (S, 2)
        batch = max(1, 4_000_000 // len(offsets))
        for start in range(0, len(group), batch):
            idx = group[start:start + batch]
            t = tris_px[idx]                                  # (B, 3, 2)
            centres = lo[idx][:, None, :] + offsets[None]     # (B, S, 2) pixel indices
            p = centres + 0.5                                 # their centres
            a, b, c = t[:, 0][:, None], t[:, 1][:, None], t[:, 2][:, None]
            d1 = (p[..., 0] - b[..., 0]) * (a[..., 1] - b[..., 1]) - (a[..., 0] - b[..., 0]) * (p[..., 1] - b[..., 1])
            d2 = (p[..., 0] - c[..., 0]) * (b[..., 1] - c[..., 1]) - (b[..., 0] - c[..., 0]) * (p[..., 1] - c[..., 1])
            d3 = (p[..., 0] - a[..., 0]) * (c[..., 1] - a[..., 1]) - (c[..., 0] - a[..., 0]) * (p[..., 1] - a[..., 1])
            inside = ~(((d1 < 0) | (d2 < 0) | (d3 < 0)) & ((d1 > 0) | (d2 > 0) | (d3 > 0)))
            inside &= (centres >= 0).all(axis=-1) & (centres < res).all(axis=-1)
            hit = centres[inside]
            mask[hit[:, 1], hit[:, 0]] = True
    return mask


def paint_snow_into_texture(map_obj, surface, covered):
    """Paint the *covered* faces -- exactly the preview's -- white into
    *map_obj*'s MMU_Paint texture: every pixel whose centre lies on one of
    them, over the texture's top-down projection. Water, roads, buildings
    and trails stay. Returns the number of pixels painted."""
    import ast

    from . import texture

    mesh = map_obj.data
    image = texture.find_paint_image(map_obj)
    if image is None or not image.size[0] or not covered.any():
        return 0
    res = image.size[0]
    if image.size[1] != res:
        return 0
    min_x, min_y, width, height = texture._compute_local_bbox(map_obj)
    if width <= 0 or height <= 0:
        return 0
    # Covered faces in the map's local space, then in pixel units.
    inv = np.linalg.inv(np.array(map_obj.matrix_world, dtype=np.float64))
    corners = surface.co[surface.tris[covered]]                       # (K, 3, 3) world
    local = corners @ inv[:3, :3].T + inv[:3, 3]
    tris_px = np.stack([(local[..., 0] - min_x) / width * res,
                        (local[..., 1] - min_y) / height * res], axis=-1)
    snow = _rasterize_triangles(tris_px, res)

    pixels = np.empty(res * res * 4, dtype=np.float32)
    image.pixels.foreach_get(pixels)
    arr = pixels.reshape((res, res, 4))
    rgb = np.rint(arr[..., :3] * 255.0)
    for color in _protected_colors(mesh):
        snow &= ~(np.abs(rgb - np.asarray(color, dtype=np.float64)) <= 1.0).all(axis=-1)
    if not snow.any():
        return 0

    # Keep the base-colour anchor block and the side-wall cells (see
    # texture.bake_height_layer_into_texture) as they are.
    cell = texture._SIDE_CELL
    kept = {
        (rr, cc): arr[rr * cell:(rr + 1) * cell, cc * cell:(cc + 1) * cell].copy()
        for rr, cc in texture._used_side_cells(mesh, res)
    }
    anchor = arr[0:4, 0:4].copy()
    arr[snow] = (SNOW_SRGB[0] / 255.0, SNOW_SRGB[1] / 255.0, SNOW_SRGB[2] / 255.0, 1.0)
    arr[0:4, 0:4] = anchor
    for (rr, cc), block in kept.items():
        arr[rr * cell:(rr + 1) * cell, cc * cell:(cc + 1) * cell] = block
    image.pixels.foreach_set(arr.ravel())
    image.update()
    image.pack()

    # The 3MF filament palette gets the snow colour, like a Color by Height band.
    try:
        palette = ast.literal_eval(mesh.get("3mf_paint_extruder_colors", "{}"))
    except (ValueError, SyntaxError):
        palette = {}
    if not isinstance(palette, dict):
        palette = {}
    texture._sync_height_bake_palette(mesh, palette, arr, texture._srgb_to_hex(*SNOW_SRGB))
    mesh["3mf_paint_extruder_colors"] = str(palette)
    return int(snow.sum())


def paint_snow_onto_faces(map_obj, surface, covered):
    """Give the covered faces of a map colored by face materials the snow
    material -- a white Color by Height band (it can be stacked on and
    recolored like one). Faces in a protected role's material stay.
    Returns the number of faces painted."""
    from .. import operators
    from .color_styles import material_role

    mesh = map_obj.data
    if surface.poly_count != len(mesh.polygons):
        return 0  # the mesh changed since the surface was read
    polys = np.unique(surface.poly[covered])
    if not len(polys):
        return 0
    index = np.empty(len(mesh.polygons), dtype=np.int32)
    mesh.polygons.foreach_get("material_index", index)
    protected = [i for i, m in enumerate(mesh.materials) if material_role(m) in PROTECTED_ROLES]
    polys = polys[~np.isin(index[polys], protected)]
    if not len(polys):
        return 0
    material = operators._height_color_material(tuple(c / 255.0 for c in SNOW_SRGB))
    slot = mesh.materials.find(material.name)
    if slot < 0:
        mesh.materials.append(material)
        slot = len(mesh.materials) - 1
    index[polys] = slot
    mesh.polygons.foreach_set("material_index", index)
    mesh.update()
    names = [str(n) for n in map_obj.get(operators._HEIGHT_COLOR_MATERIALS_PROP, [])]
    if material.name not in names:
        map_obj[operators._HEIGHT_COLOR_MATERIALS_PROP] = names + [material.name]
    return int(len(polys))
